<?php
namespace App\Services;
use Illuminate\Http\Client\PendingRequest; use Illuminate\Support\Facades\Http; use RuntimeException; use Throwable;
class CpanelService { private function client(): PendingRequest{$c=config('ikontrol.cpanel');if(!$c['host']||!$c['token'])throw new RuntimeException('cPanel no esta configurado.');return Http::acceptJson()->timeout(20)->withHeaders(['Authorization'=>'cpanel '.$c['username'].':'.$c['token']]);} private function call(string $module,string $function,array $params=[]):array{try{$c=config('ikontrol.cpanel');$url='https://'.preg_replace('#^https?://#','',$c['host']).':'.$c['port'].'/execute/'.$module.'/'.$function;$r=$this->client()->get($url,$params)->throw()->json();if(($r['status']??0)!==1)throw new RuntimeException();return $r;}catch(Throwable){throw new RuntimeException('No fue posible completar la operacion con cPanel.');}} public function testConnection():array{return $this->call('Variables','get_user_information');} public function createDatabase(string $name):array{return $this->call('Mysql','create_database',['name'=>$name]);} public function assignUserToDatabase(string $database):array{return $this->call('Mysql','set_privileges_on_database',['user'=>config('ikontrol.cpanel.username'),'database'=>$database,'privileges'=>'ALL PRIVILEGES']);} public function databaseExists(string $name):bool{$r=$this->call('Mysql','list_databases');return collect($r['data']??[])->contains(fn($db)=>($db['database']??$db['name']??null)===$name);} }
